-- Seed catalogue service items + required documents so clients can file requests.
-- Generated from the verified reference catalogue. Idempotent: parents are
-- resolved by CODE (works on empty prod and already-seeded dev), and every
-- INSERT is ON CONFLICT DO NOTHING. JSON/text use dollar-quoting ($v$) so
-- Arabic text, quotes and newlines are preserved exactly.

-- SUPPLEMENT_LABEL_FULL  (Supplement label assessment (full 113-item))
INSERT INTO "ServiceItem" ("id","subCategoryId","code","nameEn","nameAr","descEn","descAr","basePrice","vatRate","resubmissionPricePct","slaHours","freeResubmissions","maxResubmissions","productAttrSchema","checkSets","sortOrder","active") VALUES (
  $v$svc_supplement_label_full$v$,
  (SELECT "id" FROM "SubCategory" WHERE "code" = $v$FOOD_SUPPLEMENTS$v$),
  $v$SUPPLEMENT_LABEL_FULL$v$, $v$Supplement label assessment (full 113-item)$v$, $v$تقييم بطاقة المكمل الغذائي (113 بنداً كاملاً)$v$, $v$Full conformity assessment against GSO 9, FD 55, FD 2233, FD 2333 and FD 2500.$v$, $v$تقييم مطابقة كامل وفق GSO 9 وFD 55 وFD 2233 وFD 2333 وFD 2500.$v$,
  4500, 0.15, 0.5, 120, 0, 3,
  $v${"type":"object","required":["dosage_form","target_group","contains_fish_oil","has_nutrition_claim","has_health_claim"],"properties":{"dosage_form":{"enum":["capsule","tablet","chewable","powder","liquid","softgel","gummy","sachet"],"type":"string","helpAr":"يحدد أي ملاحظات FD 2500 وقواعد القابل للمضغ تنطبق على المنتج.","helpEn":"Drives which FD 2500 notes and chewable-specific rules apply.","titleAr":"شكل الجرعة","titleEn":"Dosage form"},"target_group":{"enum":["adult","child","pregnant","athlete","elderly"],"type":"string","helpAr":"يُستخدم لجعل تحذيرات العمر قابلة للتطبيق أو غير منطبقة.","helpEn":"Used to mark age-specific warnings as applicable or N/A.","titleAr":"الفئة المستهدفة","titleEn":"Target group"},"has_health_claim":{"type":"boolean","helpAr":"يفتح فحوصات إثبات ادعاءات الجدولين 1 و2.","helpEn":"Opens Table 1/2 claim substantiation checks.","titleAr":"يتضمن ادعاءً صحياً","titleEn":"Has health claim"},"contains_fish_oil":{"type":"boolean","helpAr":"يشغّل فحوصات مسببات الحساسية ومصدر أوميغا.","helpEn":"Triggers allergen and source-of-omega labelling checks.","titleAr":"يحتوي على زيت السمك","titleEn":"Contains fish oil"},"has_nutrition_claim":{"type":"boolean","helpAr":"يفتح شروط ادعاءات التغذية في FD 2333 للتقييم.","helpEn":"Opens FD 2333 nutrition-claim conditions for scoring.","titleAr":"يتضمن ادعاءً تغذوياً","titleEn":"Has nutrition claim"}}}$v$::jsonb,
  $v$[{"code":"GSO_9","items":[{"code":"GSO_9_01","titleAr":"هل اسم المنتج موجود؟","titleEn":"Is the product name present?","category":"Product Identity","priority":"Critical","compliantWhen":"A clear product name appears on the principal display panel and identifies the food product","knowledgeBaseAr":"اسم المنتج: الاسم الذي يعرّف المنتج الغذائي ويميزه عن المنتجات الأخرى. ويجب أن يظهر على واجهة العرض الرئيسية.","knowledgeBaseEn":"Product Name: The name that identifies the food product and distinguishes it from other products. It shall appear on the principal display panel.","evidenceRequired":"Principal display panel and complete label artwork","commonNonConformities":"Product name is missing, obscured, or not shown on the principal display panel"},{"code":"GSO_9_02","titleAr":"هل يعبّر الاسم عن الطبيعة الحقيقية للمنتج؟","titleEn":"Does the name express the true nature of the product?","category":"Product Identity","priority":"High","compliantWhen":"The name accurately reflects the product’s true nature, identity, type, and composition","knowledgeBaseAr":"يجب أن يصف اسم المنتج بدقة طبيعته الحقيقية وهويته ونوعه، وألا يوحي بتركيب أو جودة أو فئة مختلفة.","knowledgeBaseEn":"The product name shall accurately describe the true nature, identity, and type of the food. It shall not imply a different composition, quality, or category.","evidenceRequired":"Product name, product specification, composition, and label artwork","commonNonConformities":"The name implies an incorrect composition, quality, identity, or product category"},{"code":"GSO_9_03","titleAr":"هل الاسم غير مضلِّل؟","titleEn":"Is the name non-misleading?","category":"Product Identity","priority":"Critical","compliantWhen":"The name and associated presentation are truthful and do not mislead about nature, composition, origin, quality, or characteristics","knowledgeBaseAr":"يجب ألا يتضمن اسم المنتج أي كلمات أو أوصاف أو رموز أو علامات تجارية أو صور كاذبة أو خادعة أو مضللة بشأن طبيعة المنتج أو تركيبه أو منشئه أو جودته أو خصائصه.","knowledgeBaseEn":"The product name shall not contain any false, deceptive, or misleading words, descriptions, symbols, trademarks, or illustrations regarding the product's nature, composition, origin, quality, or characteristics.","evidenceRequired":"Product name, claims, symbols, trademarks, illustrations, and supporting product information","commonNonConformities":"False, deceptive, exaggerated, or misleading wording, symbols, trademarks, or illustrations are used"},{"code":"GSO_9_04","titleAr":"هل توجد قائمة بالمكوّنات؟","titleEn":"Is there a list of ingredients?","category":"Ingredients & Allergens","priority":"Critical","compliantWhen":"A complete ingredient list declares all ingredients, compound ingredients, additives, and required processing ingredients","knowledgeBaseAr":"قائمة المكونات: قائمة كاملة بجميع المكونات المستخدمة في تصنيع المنتج، بما في ذلك المكونات المركبة والمضافات الغذائية ومكونات المعالجة حيثما يلزم.","knowledgeBaseEn":"Ingredients List: A complete list of all ingredients used in the manufacture of the product, including compound ingredients, food additives, and processing ingredients where required.","evidenceRequired":"Ingredient list, formulation, bill of materials, additive list, and compound-ingredient details","commonNonConformities":"Ingredient list is missing or one or more required ingredients, additives, or compound ingredients are omitted"},{"code":"GSO_9_05","titleAr":"هل رُتِّبت المكوّنات تنازلياً حسب الوزن؟","titleEn":"Are ingredients arranged in descending order by weight?","category":"Ingredients & Allergens","priority":"High","compliantWhen":"Ingredients are ordered from greatest to least by manufacturing weight","knowledgeBaseAr":"يجب التصريح بالمكونات بترتيب تنازلي حسب أوزانها وقت التصنيع، بدءًا بالمكوّن الموجود بأكبر كمية.","knowledgeBaseEn":"Ingredients shall be declared in descending order of their weight at the time of manufacture, beginning with the ingredient present in the greatest amount.","evidenceRequired":"Ingredient list and formulation quantities at the time of manufacture","commonNonConformities":"Ingredients are presented in the wrong sequence or the declared order conflicts with the formulation"},{"code":"GSO_9_06","titleAr":"هل تم الإفصاح عن المضافات الغذائية بالطريقة النظامية؟","titleEn":"Are food additives disclosed in the regulatory manner?","category":"Ingredients & Allergens","priority":"High","compliantWhen":"Each food additive is declared by functional class followed by its specific name or INS number","knowledgeBaseAr":"يجب التصريح بالمضافات الغذائية بذكر فئتها الوظيفية متبوعة باسمها المحدد أو رقم النظام الدولي للترقيم (INS)، مثل: مادة حافظة: بنزوات الصوديوم (INS 211).","knowledgeBaseEn":"Food additives shall be declared by their functional class followed by their specific name or INS number (e.g., Preservative: Sodium Benzoate (INS 211)).","evidenceRequired":"Ingredient list, additive specification, formulation, and applicable additive records","commonNonConformities":"Additive is omitted, incorrectly named, lacks its functional class, or uses an incorrect INS number"},{"code":"GSO_9_07","titleAr":"هل تم الإفصاح عن مسبّبات الحساسية عند وجودها؟","titleEn":"Are allergens disclosed when present?","category":"Ingredients & Allergens","priority":"Critical","compliantWhen":"All allergens present in the product are clearly and correctly declared","knowledgeBaseAr":"يجب الإفصاح عن مسببات الحساسية عند وجودها، بما في ذلك الحبوب المحتوية على الغلوتين، والقشريات، والبيض، والأسماك، والفول السوداني، وفول الصويا، والحليب، والمكسرات الشجرية، والسمسم، والكبريتيت عند الاقتضاء.","knowledgeBaseEn":"Allergens shall be declared when present, including cereals containing gluten, crustaceans, eggs, fish, peanuts, soybeans, milk, tree nuts, sesame, and sulphites where applicable.","evidenceRequired":"Ingredient list, formulation, allergen assessment, supplier declarations, and cross-contact review","commonNonConformities":"A present allergen is omitted, hidden, ambiguous, or not emphasized as required"},{"code":"GSO_9_08","titleAr":"هل تم بيان المحتوى الصافي؟","titleEn":"Is the net content indicated?","category":"Mandatory Information","priority":"High","compliantWhen":"The actual food quantity excluding packaging is clearly declared by weight, volume, or count as appropriate","knowledgeBaseAr":"المحتوى الصافي: الكمية الفعلية من الغذاء الموجودة داخل العبوة، باستثناء مواد التعبئة والتغليف، ويُعبّر عنها بالوزن أو الحجم أو العدد حسب الاقتضاء.","knowledgeBaseEn":"Net Content: The actual quantity of food contained in the package, excluding packaging material, expressed by weight, volume, or count as appropriate.","evidenceRequired":"Principal display panel, package specification, and declared net quantity","commonNonConformities":"Net content is missing, includes packaging, or does not represent the actual quantity"},{"code":"GSO_9_09","titleAr":"هل استُخدمت وحدة القياس الصحيحة؟","titleEn":"Is the correct unit of measurement used?","category":"Mandatory Information","priority":"Medium","compliantWhen":"An approved metric unit appropriate to the product is used, such as g, kg, mL, L, or unit count","knowledgeBaseAr":"يجب التصريح بالكمية الصافية باستخدام وحدات مترية معتمدة مثل g أو kg أو mL أو L أو عدد الوحدات، وفقًا لطبيعة المنتج.","knowledgeBaseEn":"Net quantity shall be declared using approved metric units such as g, kg, mL, L, or number of units, depending on the nature of the product.","evidenceRequired":"Net quantity statement and package/product specification","commonNonConformities":"Incorrect, non-metric, unsuitable, or missing measurement unit"},{"code":"GSO_9_10","titleAr":"هل اسم المُصنِّع/المنتِج موجود؟","titleEn":"Is the manufacturer/producer name present?","category":"Mandatory Information","priority":"High","compliantWhen":"The manufacturer, producer, packer, or responsible food business operator is clearly named","knowledgeBaseAr":"يجب ذكر اسم المُصنّع أو المُنتِج أو المُعبّئ أو مشغّل المنشأة الغذائية المسؤول على البطاقة.","knowledgeBaseEn":"The name of the manufacturer, producer, packer, or the responsible food business operator shall be declared on the label.","evidenceRequired":"Label artwork and responsible food business operator records","commonNonConformities":"Responsible operator name is absent, incomplete, or inconsistent with supporting records"},{"code":"GSO_9_11","titleAr":"هل العنوان موجود؟","titleEn":"Is the address present?","category":"Mandatory Information","priority":"High","compliantWhen":"A sufficient physical address identifies the responsible manufacturer, producer, packer, importer, or operator","knowledgeBaseAr":"يجب تقديم العنوان الفعلي للمُصنّع أو المُنتِج أو المُعبّئ أو المستورد أو مشغّل المنشأة المسؤول بما يتيح التعريف والتتبع.","knowledgeBaseEn":"The physical address of the manufacturer, producer, packer, importer, or responsible business operator shall be provided to allow identification and traceability.","evidenceRequired":"Label artwork, company registration details, and traceability records","commonNonConformities":"Address is missing, incomplete, non-physical, or insufficient for identification and traceability"},{"code":"GSO_9_12","titleAr":"هل تم بيان بلد المنشأ؟","titleEn":"Is the country of origin indicated?","category":"Mandatory Information","priority":"Critical","compliantWhen":"The true country of manufacture or production is clearly and accurately declared","knowledgeBaseAr":"بلد المنشأ: البلد الذي صُنّع أو أُنتج فيه المنتج. ويجب ألا يضلل المنشأ المعلن المستهلكين بشأن المنشأ الحقيقي للمنتج.","knowledgeBaseEn":"Country of Origin: The country where the product was manufactured or produced. The declared origin shall not mislead consumers regarding the true origin of the product.","evidenceRequired":"Country-of-origin statement, manufacturing records, import documents, and label artwork","commonNonConformities":"Origin is missing, false, ambiguous, or presented in a way that may mislead consumers"},{"code":"GSO_9_13","titleAr":"هل تم بيان تاريخ الإنتاج؟","titleEn":"Is the production date indicated?","category":"Mandatory Information","priority":"High","compliantWhen":"The production date is present, legible, and declared in the approved format","knowledgeBaseAr":"تاريخ الإنتاج: التاريخ الذي صُنّع أو أُنتج فيه المنتج، ويُصرّح به وفق صيغة التاريخ المعتمدة.","knowledgeBaseEn":"Production Date: The date on which the product was manufactured or produced, declared in the approved date format.","evidenceRequired":"Date marking on the package, production records, and approved date format","commonNonConformities":"Production date is missing, illegible, incorrect, or uses an unapproved format"},{"code":"GSO_9_14","titleAr":"هل تم بيان تاريخ انتهاء الصلاحية؟","titleEn":"Is the expiry date indicated?","category":"Mandatory Information","priority":"Critical","compliantWhen":"The expiry date is present, legible, correctly formatted, and supported by the approved shelf life","knowledgeBaseAr":"تاريخ انتهاء الصلاحية: آخر تاريخ يُتوقع فيه أن يظل المنتج صالحًا للاستهلاك عند حفظه وفق الشروط المحددة، ويُصرّح به وفق صيغة التاريخ المعتمدة.","knowledgeBaseEn":"Expiry Date: The last date on which the product is expected to remain suitable for consumption when stored under the specified conditions, declared in the approved date format.","evidenceRequired":"Expiry marking, shelf-life evidence, storage conditions, and approved date format","commonNonConformities":"Expiry date is missing, illegible, expired, incorrectly formatted, or unsupported by shelf-life evidence"},{"code":"GSO_9_15","titleAr":"هل توجد تعليمات التخزين؟","titleEn":"Are storage instructions present?","category":"Mandatory Information","priority":"High","compliantWhen":"Applicable storage conditions are clearly stated and match the conditions needed to maintain safety and quality","knowledgeBaseAr":"شروط التخزين: التعليمات اللازمة للحفاظ على سلامة المنتج وجودته، مثل «يُحفظ في مكان بارد وجاف» أو «يُحفظ مبردًا» أو غيرها من الشروط المنطبقة.","knowledgeBaseEn":"Storage Conditions: Instructions necessary to maintain the product's safety and quality, such as \"Store in a cool, dry place,\" \"Keep refrigerated,\" or other applicable conditions.","evidenceRequired":"Storage statement, product specification, stability evidence, and label artwork","commonNonConformities":"Storage instructions are missing, incomplete, unclear, or inconsistent with stability requirements"},{"code":"GSO_9_16","titleAr":"هل يوجد رقم التشغيلة/الدفعة؟","titleEn":"Is the batch/lot number present?","category":"Mandatory Information","priority":"Critical","compliantWhen":"A clear and unique batch or lot code links the product to its production records","knowledgeBaseAr":"رقم التشغيلة/الدفعة: رمز فريد يحدد دفعة إنتاج معينة لأغراض التتبع ومراقبة الجودة واستدعاء المنتج.","knowledgeBaseEn":"Batch/Lot Number: A unique code identifying a specific production batch for traceability, quality control, and product recall purposes.","evidenceRequired":"Batch/lot code on the package, production records, and traceability system","commonNonConformities":"Batch/lot code is missing, illegible, duplicated, or cannot support traceability and recall"},{"code":"GSO_9_17","titleAr":"هل جميع البيانات واضحة وسهلة القراءة؟","titleEn":"Are all data clear and easy to read?","category":"Presentation & Language","priority":"High","compliantWhen":"All mandatory information is legible, permanent, conspicuous, and easy to read","knowledgeBaseAr":"يجب أن تكون جميع بيانات البطاقة الإلزامية مقروءة ودائمة وواضحة الظهور، وأن تُقدّم بطريقة يسهل على المستهلكين قراءتها في الظروف المعتادة للشراء والاستخدام.","knowledgeBaseEn":"Mandatory labeling information shall be legible, permanent, clearly visible, and presented in a manner that is easy for consumers to read under normal conditions of purchase and use.","evidenceRequired":"Physical label or print proof under normal purchase and use conditions","commonNonConformities":"Mandatory data is blurred, removable, hidden, obscured, low-contrast, or otherwise difficult to read"},{"code":"GSO_9_18","titleAr":"هل استُخدمت اللغة العربية وفق المتطلبات؟","titleEn":"Is Arabic language used according to requirements?","category":"Presentation & Language","priority":"Critical","compliantWhen":"All mandatory information is provided in Arabic and every additional language is consistent with it","knowledgeBaseAr":"يجب تقديم جميع بيانات البطاقة الإلزامية باللغة العربية. ويجوز استخدام لغات إضافية شريطة اتساقها مع النص العربي وعدم تغيير معناه.","knowledgeBaseEn":"All mandatory labeling information shall be provided in Arabic. Additional languages may be used provided they are consistent with the Arabic text and do not alter its meaning.","evidenceRequired":"Arabic label artwork and side-by-side comparison of all language versions","commonNonConformities":"Mandatory Arabic text is missing, incomplete, mistranslated, or contradicted by another language"},{"code":"GSO_9_19","titleAr":"هل حجم الخط مناسب؟","titleEn":"Is the font size appropriate?","category":"Presentation & Language","priority":"Medium","compliantWhen":"Mandatory information uses a sufficiently large and clear font without reducing visibility","knowledgeBaseAr":"يجب أن يكون حجم خط بيانات البطاقة الإلزامية كبيرًا وواضحًا بما يكفي لضمان سهولة القراءة، وألا يحجب البيانات الإلزامية أو يقلل من وضوحها.","knowledgeBaseEn":"The font size of mandatory labeling information shall be sufficiently large and clear to ensure readability and shall not obscure or reduce the visibility of mandatory information.","evidenceRequired":"Final-size label artwork, physical label, and font-size measurement","commonNonConformities":"Font is too small, condensed, obscured, or otherwise compromises readability"}],"titleAr":"البطاقات الغذائية العامة (GSO 9)","titleEn":"General Labeling (GSO 9)","standard":"SFDA FD. GSO 9","itemCount":19},{"code":"FD_55","items":[{"code":"FD_55_01","titleAr":"هل صُنّف المنتج كمكمّل غذائي وفق التعريف القياسي؟","titleEn":"Is the product classified as a dietary supplement according to the standard definition?","category":"Classification","priority":"Critical","compliantWhen":"Product meets the dietary-supplement definition and contains concentrated nutritional or physiological substances for dose-based use","knowledgeBaseAr":"المكمل الغذائي هو منتج غذائي يهدف إلى استكمال النظام الغذائي الطبيعي، ويحتوي على مصدر مركز لعنصر غذائي واحد أو أكثر أو لمواد ذات تأثير غذائي أو فسيولوجي، ويستهلك بجرعات محددة، ولا يهدف إلى علاج الأمراض أو تشخيصها أو الوقاية منها.","evidenceRequired":"Product composition, intended-use statement, product specification","commonNonConformities":"Product does not meet the dietary-supplement definition or lacks a qualifying nutritional/physiological purpose"},{"code":"FD_55_02","titleAr":"هل المنتج ليس دواءً ولا مُستحضراً عشبياً ولا أي منتج خارج نطاق المكملات الغذائية؟","titleEn":"Is the product neither a medicine, herbal preparation, nor any product outside the scope of dietary supplements?","category":"Classification","priority":"Critical","compliantWhen":"Product is not regulated as a medicine, therapeutic herbal preparation, medical device, or another excluded product type","knowledgeBaseAr":"لا يعتبر المنتج مكملًا غذائيًا إذا كان دواءً، أو مستحضرًا عشبيًا علاجيًا، أو مستحضرًا طبيًا، أو جهازًا طبيًا، أو أي منتج يخضع لأنظمة تنظيمية أخرى غير المكملات الغذائية.","evidenceRequired":"Regulatory classification file and product presentation","commonNonConformities":"Product is medicinal, therapeutic, a medical device, or otherwise outside the dietary-supplement scope"},{"code":"FD_55_03","titleAr":"هل المنتج مُعدّ لدعم أو تكملة النظام الغذائي الطبيعي وليس لعلاج أو تشخيص أو الوقاية من الأمراض؟","titleEn":"Is the product intended to support or supplement the normal diet rather than treat, diagnose, or prevent diseases?","category":"Classification","priority":"Critical","compliantWhen":"Intended use is limited to supplementing the diet or supporting normal physiological functions","knowledgeBaseAr":"الغرض من المكمل الغذائي هو استكمال النظام الغذائي أو دعم الوظائف الفسيولوجية الطبيعية، وليس علاج الأمراض أو تشخيصها أو الوقاية منها أو تخفيف أعراضها.","evidenceRequired":"Claims, intended-use statement, label, and marketing materials","commonNonConformities":"Disease treatment, diagnosis, prevention, or symptom-relief claims are made"},{"code":"FD_55_04","titleAr":"هل المنتج غير مُقدّم بشكل صيدلاني (كالكبسولات أو الأقراص أو الحبوب أو الحقن) ولا يُقدّم أو يُغلّف بطريقة توحي بأنه منتج دوائي؟","titleEn":"Is the product not presented in a pharmaceutical form (such as capsules, tablets, pills, or injections), and not presented or packaged in a way that suggests it is a medicinal product?","category":"Classification","priority":"High","compliantWhen":"Presentation does not imply a medicinal product and contains no medicinal naming or therapeutic positioning","knowledgeBaseAr":"يجب ألا يُعرض أو يُسوَّق المنتج بطريقة توحي بأنه دواء، مثل استخدام أسماء دوائية أو ادعاءات علاجية أو تصميم عبوة يوحي بأنه منتج صيدلاني، حتى وإن كان في صورة كبسولات أو أقراص أو مسحوق أو سائل.","evidenceRequired":"Dosage form, label design, product name, claims, and packaging","commonNonConformities":"Packaging, naming, or claims present the product as a medicine"},{"code":"FD_55_05","titleAr":"هل اسم المنتج مناسب وغير مضلِّل للمستهلك؟","titleEn":"Is the product name appropriate and not misleading to the consumer?","category":"Labeling","priority":"High","compliantWhen":"Product name is accurate, appropriate, and not misleading about identity or benefit","knowledgeBaseAr":"يجب ألا يحتوي اسم المنتج على ادعاءات علاجية أو أسماء توحي بالشفاء أو الوقاية أو التشخيص، وألا يسبب تضليلًا للمستهلك بشأن طبيعة المنتج أو فوائده.","evidenceRequired":"Principal display panel and product artwork","commonNonConformities":"Misleading, therapeutic, preventive, or deceptive product name"},{"code":"FD_55_06","titleAr":"هل تم ذكر اسم الفئة (مكمل غذائي / Dietary Supplement) عند الاقتضاء؟","titleEn":"Is the category name (Dietary Supplement / مكمل غذائي) stated where applicable?","category":"Labeling","priority":"High","compliantWhen":"The category name “Dietary Supplement / مكمل غذائي” is clearly stated when required","knowledgeBaseAr":"يجب أن يظهر على البطاقة اسم الفئة \"مكمل غذائي\" أو \"Dietary Supplement\" بصورة واضحة عند وجوب ذلك.","evidenceRequired":"Principal display panel and bilingual label artwork","commonNonConformities":"Required category statement is missing, unclear, or incorrectly worded"},{"code":"FD_55_07","titleAr":"هل تم بيان الشكل الجرعي / طريقة التناول بوضوح على الملصق؟","titleEn":"Is the dosage form / method of administration clearly stated on the label?","category":"Labeling","priority":"Medium","compliantWhen":"Dosage form or administration method is clearly identified where applicable","knowledgeBaseAr":"يجب توضيح شكل المنتج أو طريقة تناوله مثل: كبسولات، أقراص، مسحوق، سائل، أكياس، أقراص للمضغ، أقراص فوارة، قطرات، مع بيان طريقة الاستخدام إذا لزم الأمر.","evidenceRequired":"Label artwork and directions for use","commonNonConformities":"Dosage form or method of administration is absent or unclear"},{"code":"FD_55_08","titleAr":"هل تم بيان الكمية الصافية أو عدد الوحدات؟","titleEn":"Is the net quantity or number of units stated?","category":"Labeling","priority":"High","compliantWhen":"Net quantity, volume, weight, or number of units is clearly stated","knowledgeBaseAr":"يجب بيان الكمية الصافية مثل الوزن أو الحجم، أو عدد الوحدات داخل العبوة مثل 30 كبسولة أو 60 قرصًا أو 250 مل.","evidenceRequired":"Principal display panel and package contents","commonNonConformities":"Net quantity or unit count is missing, incorrect, or not clearly visible"},{"code":"FD_55_09","titleAr":"هل تم إدراج جميع المكوّنات الغذائية الفعّالة؟","titleEn":"Are all active nutritional ingredients listed?","category":"Composition & Use","priority":"Critical","compliantWhen":"All active nutritional ingredients are declared on the label","knowledgeBaseAr":"يجب إدراج جميع المكونات الغذائية الفعالة مثل الفيتامينات، المعادن، الأحماض الأمينية، الأحماض الدهنية، المستخلصات النباتية، البروبيوتيك أو أي مكون غذائي فعال آخر.","evidenceRequired":"Ingredient list, formulation, specification, and label","commonNonConformities":"One or more active nutritional ingredients are omitted or ambiguously identified"},{"code":"FD_55_10","titleAr":"هل تم بيان كمية كل مكوّن فعّال لكل جرعة؟","titleEn":"Is the quantity of each active ingredient stated per dose?","category":"Composition & Use","priority":"Critical","compliantWhen":"Quantity of every active ingredient is stated per recommended dose","knowledgeBaseAr":"يجب بيان كمية كل مكون فعال لكل جرعة موصى بها، وليس فقط لكل عبوة.","evidenceRequired":"Supplement facts panel, formulation, and recommended dose","commonNonConformities":"Amount is missing, declared only per pack, or not linked to the recommended dose"},{"code":"FD_55_11","titleAr":"هل وحدات قياس المكوّنات صحيحة (ملغ، ميكروغرام، IU، غ، مل، إلخ)؟","titleEn":"Are the units of measurement for the ingredients correct (mg, µg, IU, g, mL, etc.)?","category":"Composition & Use","priority":"High","compliantWhen":"Each ingredient quantity uses an appropriate recognized unit such as g, mg, µg, IU, or mL","knowledgeBaseAr":"تستخدم الوحدات المناسبة حسب نوع المادة مثل g، mg، µg، IU، mL أو غيرها من الوحدات المعترف بها.","evidenceRequired":"Supplement facts panel and ingredient specification","commonNonConformities":"Incorrect, missing, inconsistent, or unsuitable units are used"},{"code":"FD_55_12","titleAr":"هل تم إدراج جميع المكوّنات الأخرى (المكوّنات غير الفعّالة / السواغات)؟","titleEn":"Are all other ingredients (inactive ingredients / excipients) listed?","category":"Composition & Use","priority":"High","compliantWhen":"All inactive ingredients and excipients are declared where applicable","knowledgeBaseAr":"يجب إدراج جميع المكونات غير الفعالة مثل المواد المالئة، المثبتات، الملونات، المنكهات، المحليات، المواد الحافظة، والكبسولة نفسها عند الاقتضاء.","evidenceRequired":"Full ingredient list, formulation, excipient declaration, and capsule shell details","commonNonConformities":"Fillers, stabilizers, colors, flavors, sweeteners, preservatives, or shell ingredients are omitted"},{"code":"FD_55_13","titleAr":"هل تم بيان الجرعة اليومية الموصى بها؟","titleEn":"Is the recommended daily dose stated?","category":"Composition & Use","priority":"Critical","compliantWhen":"Recommended daily dose is stated clearly and unambiguously","knowledgeBaseAr":"يجب تحديد الجرعة اليومية الموصى بها بوضوح مثل: كبسولة واحدة يوميًا، أو قرصان يوميًا، أو 5 مل يوميًا.","evidenceRequired":"Directions for use and recommended-dose statement","commonNonConformities":"Recommended daily dose is missing, incomplete, or unclear"},{"code":"FD_55_14","titleAr":"هل تم بيان تعليمات الاستخدام بوضوح؟","titleEn":"Are the instructions for use stated clearly?","category":"Composition & Use","priority":"High","compliantWhen":"Instructions explain how and when to take or prepare the product where needed","knowledgeBaseAr":"يجب أن توضح تعليمات الاستخدام مثل وقت التناول، طريقة التحضير، الحاجة إلى الماء، أو تناول المنتج مع الطعام إذا كان ذلك ضروريًا.","evidenceRequired":"Directions for use and preparation instructions","commonNonConformities":"Use, timing, preparation, water, or food-related instructions are missing or unclear"},{"code":"FD_55_15","titleAr":"هل تم تحديد الفئة المستهدفة عند الضرورة؟","titleEn":"Is the intended user group specified where necessary?","category":"Composition & Use","priority":"Medium","compliantWhen":"Intended user group is specified whenever the product targets a particular population","knowledgeBaseAr":"يجب تحديد الفئة المستهدفة عندما يكون المنتج مخصصًا لفئة معينة مثل البالغين، الأطفال، كبار السن، الرياضيين أو النساء.","evidenceRequired":"Label, product specification, and target-population justification","commonNonConformities":"Target population is omitted where necessary or conflicts with product suitability"},{"code":"FD_55_16","titleAr":"هل تم تضمين التحذيرات الإلزامية؟","titleEn":"Are the mandatory warnings included?","category":"Warnings & Safety","priority":"Critical","compliantWhen":"All mandatory and ingredient-specific warning statements are present","knowledgeBaseAr":"تشمل التحذيرات الإلزامية جميع العبارات التي يتطلبها النظام لهذا المنتج بالإضافة إلى التحذيرات الخاصة بالمكونات عند الحاجة.","evidenceRequired":"Warnings panel, ingredient-specific requirements, and regulatory checklist","commonNonConformities":"One or more mandatory or ingredient-specific warnings are missing"},{"code":"FD_55_17","titleAr":"هل تم تضمين تحذيرات الفئات الحساسة (الحوامل، المرضعات، الأطفال، إلخ) عند الضرورة؟","titleEn":"Are warnings for sensitive groups (pregnant women, breastfeeding women, children, etc.) included where necessary?","category":"Warnings & Safety","priority":"Critical","compliantWhen":"Applicable warnings for pregnancy, breastfeeding, children, medical conditions, or medicine users are included","knowledgeBaseAr":"يجب إدراج التحذيرات الخاصة بالفئات الحساسة إذا كان المنتج غير مناسب للحوامل أو المرضعات أو الأطفال أو مرضى معينين أو مستخدمي أدوية معينة.","evidenceRequired":"Warnings panel and safety assessment for sensitive populations","commonNonConformities":"Required sensitive-group contraindications or precautions are absent"},{"code":"FD_55_18","titleAr":"هل تم تضمين عبارة «لا تتجاوز الجرعة اليومية الموصى بها» أو ما يعادلها؟","titleEn":"Is the statement “Do not exceed the recommended daily dose,” or an equivalent statement, included?","category":"Warnings & Safety","priority":"Critical","compliantWhen":"A clear statement not to exceed the recommended daily dose is included","knowledgeBaseAr":"يجب أن تتضمن البطاقة عبارة: \"لا تتجاوز الجرعة اليومية الموصى بها\" أو عبارة تؤدي المعنى نفسه.","evidenceRequired":"Warnings panel and daily-dose statement","commonNonConformities":"The maximum-dose warning is missing or materially altered"},{"code":"FD_55_19","titleAr":"هل تم تضمين عبارة بأن المكمّل الغذائي ليس بديلاً عن النظام الغذائي المتوازن؟","titleEn":"Is a statement included that the dietary supplement is not a substitute for a balanced diet?","category":"Warnings & Safety","priority":"High","compliantWhen":"Label states that the supplement is not a substitute for a balanced and varied diet","knowledgeBaseAr":"يجب أن تتضمن البطاقة عبارة تفيد بأن المكمل الغذائي لا يغني عن النظام الغذائي المتوازن والمتنوع.","evidenceRequired":"Warnings panel and mandatory statements","commonNonConformities":"Balanced-diet substitute disclaimer is missing"},{"code":"FD_55_20","titleAr":"هل تم تضمين عبارة «يُحفظ بعيداً عن متناول الأطفال»؟","titleEn":"Is the statement “Keep out of reach of children” included?","category":"Warnings & Safety","priority":"Critical","compliantWhen":"“Keep out of reach of children” or an equivalent compliant statement is present","knowledgeBaseAr":"يجب أن تتضمن البطاقة عبارة \"يحفظ بعيدًا عن متناول الأطفال.\"","evidenceRequired":"Warnings panel and mandatory statements","commonNonConformities":"Child-safety statement is missing or unclear"},{"code":"FD_55_21","titleAr":"هل تم بيان ظروف التخزين؟","titleEn":"Are the storage conditions stated?","category":"Labeling","priority":"Medium","compliantWhen":"Required storage conditions are clearly stated and consistent with stability requirements","knowledgeBaseAr":"يجب بيان ظروف الحفظ مثل: يحفظ في مكان جاف، يحفظ بعيدًا عن الرطوبة، يحفظ دون 25°C، يحفظ بعيدًا عن أشعة الشمس، أو أي شروط تخزين خاصة بالمنتج.","evidenceRequired":"Storage statement, stability data, and product specification","commonNonConformities":"Storage conditions are missing, incomplete, or inconsistent with supporting data"},{"code":"FD_55_22","titleAr":"هل تم بيان تاريخ الإنتاج عند الاقتضاء؟","titleEn":"Is the production date stated where applicable?","category":"Labeling","priority":"Medium","compliantWhen":"Production date is stated where applicable and is clear and legible","knowledgeBaseAr":"تاريخ الإنتاج هو التاريخ الذي تم فيه تصنيع المنتج، ويذكر إذا كان النظام أو طبيعة المنتج تتطلب ذلك.","evidenceRequired":"Date marking on label and production records","commonNonConformities":"Production date is missing when required, illegible, or inconsistent with records"},{"code":"FD_55_23","titleAr":"هل تم بيان تاريخ انتهاء الصلاحية؟","titleEn":"Is the expiration date stated?","category":"Labeling","priority":"Critical","compliantWhen":"Expiration date is present, clear, legible, and consistent with shelf-life evidence","knowledgeBaseAr":"تاريخ انتهاء الصلاحية هو آخر تاريخ يضمن فيه المنتج مطابقته لمواصفاته عند حفظه بالشروط المحددة، ويجب أن يكون ظاهرًا وواضحًا.","evidenceRequired":"Date marking on label and shelf-life documentation","commonNonConformities":"Expiration date is missing, illegible, expired, or inconsistent with approved shelf life"},{"code":"FD_55_24","titleAr":"هل تمتثل لغة الملصق لمتطلبات الهيئة العامة للغذاء والدواء؟","titleEn":"Does the label language comply with SFDA requirements?","category":"Labeling","priority":"Critical","compliantWhen":"All mandatory information appears in Arabic and other languages do not conflict with or alter the Arabic meaning","knowledgeBaseAr":"يجب أن تكون جميع البيانات الإلزامية مكتوبة باللغة العربية، ويجوز إضافة لغات أخرى بشرط ألا تتعارض مع النص العربي أو تغير معناه، وأن تكون جميع المعلومات متطابقة بين اللغات.","evidenceRequired":"Arabic label artwork and comparison of all language versions","commonNonConformities":"Arabic mandatory text is missing or different language versions are inconsistent"}],"titleAr":"المكملات الغذائية (SFDA FD 55)","titleEn":"Dietary Supplement (SFDA FD 55)","standard":"SFDA.FD 55:2021","itemCount":24},{"code":"FD_2233","items":[{"code":"FD_2233_01","titleAr":"هل يقع المنتج ضمن نطاق متطلبات البطاقة الغذائية؟","titleEn":"Is the product within the scope of nutrition labeling requirements?","category":"Scope","priority":"High","compliantWhen":"Product is packaged food within standard scope","knowledgeBaseAr":"جميع المنتجات الغذائية المعبأة.\nالأغذية المعبأة المصنّعة.\nالأغذية المعبأة المستوردة.\nالأغذية المعبأة المنتجة محلياً.\nالمشروبات المعبأة.\nالمنتجات الغذائية المعبأة متعددة المكونات.\nأي غذاء معبأ غير مدرج ضمن المنتجات المعفاة في اللائحة.","knowledgeBaseEn":"All packaged food products.\nProcessed packaged foods.\nImported packaged foods.\nLocally produced packaged foods.\nPackaged beverages.\nMulti-ingredient packaged food products.\nAny packaged food not among exempted products in the standard.","evidenceRequired":"Product label, product type identification","commonNonConformities":"Claiming exemption incorrectly"},{"code":"FD_2233_02","titleAr":"هل المنتج غير مدرج ضمن المنتجات المُعفاة من المواصفة؟","titleEn":"Is the product NOT among the exempted products from the standard?","category":"Scope","priority":"High","compliantWhen":"Product does NOT fall under any exemption category","knowledgeBaseAr":"الأغذية ذات القيم الطاقية والمغذية الضئيلة التي يمكن التعبير عنها بصفر (مثل التوابل والبهارات).\nالخضار والفواكه الطازجة بما فيها خلطاتها، ما لم تكن مجففة أو مضافاً إليها مكونات.\nاللحوم والدواجن والأسماك النيئة الطازجة أو المبردة دون إضافة ماء أو توابل.\nالأغذية المباعة مباشرة للمستهلك من موقع تحضيرها (مثل السلطات والمخبوزات والحلويات والوجبات الجاهزة).\nالمنتجات الغذائية أحادية المكوّن مثل الأرز والشاي والقهوة والسكر.\nمياه الشرب المعبأة والمياه المعدنية.\nالعبوات التي تقل مساحة أكبر سطح فيها عن 25 سم².\nالمضافات الغذائية.\nالأغذية التي تتطلب تعبئة أو معالجة إضافية قبل بيعها للمستهلك.\nالعبوة الخارجية للأغذية ذاتية الخدمة إذا كانت المعلومات التغذوية على العبوة الأصلية أو على لوحة مرافقة.","knowledgeBaseEn":"Foods with negligible energy and nutrient amounts that can be expressed as zero (e.g., spices and seasonings).\nFresh vegetables and fruits, including their mixtures, unless dried or with added ingredients.\nFresh or chilled raw meat, poultry, and fish without added water or seasonings.\nFoods sold directly to consumers from the preparation site (e.g., salads, baked goods, desserts, ready meals).\nSingle-ingredient food products such as rice, tea, coffee, and sugar.\nPackaged drinking water and mineral water.\nPackages with largest surface area less than 25 cm².\nFood additives.\nFoods requiring additional packaging or processing before sale to consumers.\nOuter packaging of self-service foods if nutrition information is on original package or accompanying panel.","evidenceRequired":"Product category assessment, packaging size measurement","commonNonConformities":"Misclassifying product as exempt"},{"code":"FD_2233_03","titleAr":"هل توجد بطاقة حقائق غذائية على المنتج؟","titleEn":"Is there a nutrition facts label on the product?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Nutrition facts panel is present and visible","knowledgeBaseAr":"تعريف البطاقة التغذوية: جدول أو بيان يوضّح القيم التغذوية للمنتج وفقاً لمتطلبات اللائحة.\nقد تحمل العنوان:\nNutrition Facts\nNutrition Information\nالبيانات التغذوية\nالبطاقة التغذوية\nيجب أن تكون ظاهرة على عبوة المنتج.\nيجب أن تتضمن العناصر التغذوية الإلزامية المحددة في اللائحة (مثل الطاقة والبروتين والدهون والكربوهيدرات وغيرها).\nيمكن أن تكون باللغة العربية أو بالعربية والإنجليزية معاً وفقاً لمتطلبات البطاقة المعتمدة.","knowledgeBaseEn":"Definition of Nutrition Facts Label: A table or statement displaying the nutritional values of the product according to standard requirements.\nMay be titled:\nNutrition Facts\nNutrition Information\nالبيانات التغذوية\nالبطاقة التغذوية\nMust be visible on product packaging.\nMust include mandatory nutritional elements specified in the standard (such as energy, protein, fat, carbohydrates, etc.).\nCan be in Arabic or Arabic and English together, per approved labeling requirements.","evidenceRequired":"Visual inspection of label","commonNonConformities":"Missing nutrition facts panel entirely"},{"code":"FD_2233_04","titleAr":"هل تم بيان القيمة الطاقية (السعرات الحرارية)؟","titleEn":"Is energy value listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Energy value is declared with correct unit (kJ/kcal)","knowledgeBaseAr":"يجب أن تتضمن البطاقة التغذوية مقدار الطاقة.\nيمكن التعبير عن الطاقة بـ:\nالكيلوجول (kJ).\nالكيلوسعرة (kcal) أو السعرات الحرارية (Cal).\nأو كليهما إذا نصّت اللائحة على ذلك.\nيجب الإعلان عن الطاقة:\nلكل 100 غرام أو 100 مل، أو\nلكل حصة إذا تطلبت طريقة العرض في اللائحة ذلك.\nيجب أن تكون قيمة الطاقة رقمية مع بيان الوحدة بوضوح.\nعند استخدام الحصص يجب تحديد حجم الحصة.","knowledgeBaseEn":"Nutrition facts label must include energy amount.\nEnergy may be expressed in:\nKilojoules (kJ).\nKilocalories (kcal) or Calories (Cal).\nOr both if specified by standard.\nEnergy must be declared:\nPer 100g or 100ml, or\nPer serving if required by presentation method in standard.\nEnergy value must be numeric with unit clearly stated.\nWhen using servings, serving size must be specified.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Energy missing or wrong unit"},{"code":"FD_2233_05","titleAr":"هل تم بيان البروتين؟","titleEn":"Is protein listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Protein is declared in grams","knowledgeBaseAr":"يجب أن تتضمن البطاقة التغذوية مقدار البروتين. يُعبَّر عنه بالغرام (g)، ويُعلَن عنه لكل 100 غرام أو 100 مل أو لكل عبوة أحادية الحصة وفقاً للائحة.","knowledgeBaseEn":"Nutrition facts label must include protein amount. Expressed in grams (g), declared per 100g or 100ml or per single-serving package as per standard.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Protein value missing"},{"code":"FD_2233_06","titleAr":"هل تم بيان الكربوهيدرات؟","titleEn":"Are carbohydrates listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Total carbohydrates declared in grams","knowledgeBaseAr":"يجب أن تتضمن البطاقة مقدار إجمالي الكربوهيدرات. يُعبَّر عنه بالغرام (g)، ويُعلَن عنه لكل 100 غرام أو 100 مل أو لكل عبوة أحادية الحصة.","knowledgeBaseEn":"Label must include total carbohydrates amount. Expressed in grams (g), declared per 100g or 100ml or per single-serving package.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Carbohydrates missing"},{"code":"FD_2233_07","titleAr":"هل تم بيان إجمالي الدهون؟","titleEn":"Is total fat listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Total fat declared in grams","knowledgeBaseAr":"يجب الإعلان عن إجمالي الدهون في البطاقة التغذوية بالغرام (g) وفقاً لطريقة العرض المعتمدة.","knowledgeBaseEn":"Total fat must be declared in nutrition label in grams (g) according to approved presentation method.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Total fat missing"},{"code":"FD_2233_08","titleAr":"هل تم بيان الدهون المشبعة؟","titleEn":"Is saturated fat listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Saturated fat declared in grams","knowledgeBaseAr":"يجب الإعلان عن مقدار الدهون المشبعة بالغرام (g) في البطاقة التغذوية.","knowledgeBaseEn":"Saturated fat amount must be declared in grams (g) in nutrition label.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Saturated fat missing"},{"code":"FD_2233_09","titleAr":"هل تم بيان الدهون المتحولة؟","titleEn":"Is trans fat listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Trans fat declared in grams","knowledgeBaseAr":"يجب الإعلان عن مقدار الدهون المتحولة إذا تطلبت اللائحة ذلك أو عند كونها ضمن العناصر الإلزامية.","knowledgeBaseEn":"Trans fat amount must be declared if required by standard or when among mandatory elements.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Trans fat missing or not declared when required"},{"code":"FD_2233_10","titleAr":"هل تم بيان الكوليسترول؟","titleEn":"Is cholesterol listed?","category":"Mandatory Element","priority":"High","compliantWhen":"Cholesterol declared in mg when required","knowledgeBaseAr":"يجب الإعلان عن مقدار الكوليسترول بالمليغرام (mg) عندما تتطلب اللائحة ذلك.","knowledgeBaseEn":"Cholesterol amount must be declared in milligrams (mg) when standard requires it.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Cholesterol missing when mandatory"},{"code":"FD_2233_11","titleAr":"هل تم بيان الصوديوم؟","titleEn":"Is sodium listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Sodium declared in mg","knowledgeBaseAr":"يجب الإعلان عن مقدار الصوديوم بالمليغرام (mg).","knowledgeBaseEn":"Sodium amount must be declared in milligrams (mg).","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Sodium missing"},{"code":"FD_2233_12","titleAr":"هل تم بيان إجمالي السكريات؟","titleEn":"Is total sugars listed?","category":"Mandatory Element","priority":"Critical","compliantWhen":"Total sugars declared in grams","knowledgeBaseAr":"يجب الإعلان عن إجمالي السكريات بالغرام (g) وفقاً لمتطلبات اللائحة.","knowledgeBaseEn":"Total sugars must be declared in grams (g) per standard requirements.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Sugars missing"},{"code":"FD_2233_13","titleAr":"هل تم بيان السكريات المضافة؟","titleEn":"Is added sugars listed?","category":"Mandatory Element","priority":"High","compliantWhen":"Added sugars declared separately in grams","knowledgeBaseAr":"يجب الإعلان عن مقدار السكريات المضافة بالغرام (g) إذا تطلبت اللائحة ذلك.","knowledgeBaseEn":"Added sugars amount must be declared in grams (g) if standard requires it.","evidenceRequired":"Nutrition facts panel review","commonNonConformities":"Added sugars not separated from total"},{"code":"FD_2233_14","titleAr":"في حال وجود ادّعاء غذائي، هل تم الإفصاح عن المُغذّي ذي الصلة؟","titleEn":"If a nutrition claim is made, is the related nutrient disclosed?","category":"Claims Disclosure","priority":"High","compliantWhen":"Claimed nutrient is disclosed in nutrition panel","knowledgeBaseAr":"إذا ورد ادعاء تغذوي أو صحي بشأن مغذٍّ ما، فيجب الإفصاح عن قيمة ذلك المغذّي في البطاقة التغذوية.","knowledgeBaseEn":"If a nutrition or health claim is made about a nutrient, that nutrient's value must be disclosed in nutrition label.","evidenceRequired":"Label review for claims + nutrition panel","commonNonConformities":"Making claim without declaring nutrient value"},{"code":"FD_2233_15","titleAr":"عند وجود ادّعاء غذائي أو صحي، هل تم الإفصاح عن المُغذّيات ذات الصلة؟","titleEn":"When a nutrition or health claim exists, are the related nutrients disclosed?","category":"Claims Disclosure","priority":"High","compliantWhen":"All claim-related nutrients disclosed","knowledgeBaseAr":"يجب الإفصاح عن جميع المغذيات اللازمة لدعم الادعاء التغذوي أو الصحي وفقاً لمتطلبات اللائحة.","knowledgeBaseEn":"All nutrients necessary to support the nutrition or health claim must be disclosed per standard requirements.","evidenceRequired":"Label review for claims + nutrition panel","commonNonConformities":"Partial disclosure of claim nutrients"},{"code":"FD_2233_16","titleAr":"عند الإعلان عن الأحماض الدهنية، هل تم تحديد الأنواع المطلوبة؟","titleEn":"When fatty acids are declared, are the required types specified?","category":"Fatty Acids","priority":"Medium","compliantWhen":"All required fatty acid types specified","knowledgeBaseAr":"عند الإعلان عن الأحماض الدهنية يجب تحديد الأنواع المطلوبة (مثل المشبعة وأحادية عدم التشبع ومتعددة عدم التشبع) وفقاً للائحة.","knowledgeBaseEn":"When declaring fatty acids, required types must be specified (such as saturated, monounsaturated, polyunsaturated) per standard.","evidenceRequired":"Nutrition panel fatty acid breakdown","commonNonConformities":"Missing MUFA/PUFA when declaring fatty acids"},{"code":"FD_2233_17","titleAr":"في حال الإعلان عن الفيتامينات أو المعادن، هل تستوفي متطلبات الإعلان؟","titleEn":"If vitamins or minerals are declared, do they meet declaration requirements?","category":"Vitamins & Minerals","priority":"Medium","compliantWhen":"V&M meet minimum declaration thresholds","knowledgeBaseAr":"يجب أن تستوفي الفيتامينات والمعادن متطلبات الإعلان والحدود الدنيا المحددة في اللائحة.","knowledgeBaseEn":"Vitamins and minerals must meet declaration requirements and minimum limits specified in standard.","evidenceRequired":"Nutrition panel + specification review","commonNonConformities":"Declaring V&M below significant amount"},{"code":"FD_2233_18","titleAr":"هل تم حساب الطاقة باستخدام معاملات التحويل المعتمدة؟","titleEn":"Is energy calculated using approved conversion factors?","category":"Calculation","priority":"High","compliantWhen":"Energy calculated using approved factors","knowledgeBaseAr":"يجب حساب الطاقة باستخدام معاملات التحويل المعتمدة للمغذيات (البروتين والكربوهيدرات والدهون وغيرها وفقاً للائحة).","knowledgeBaseEn":"Energy must be calculated using approved conversion factors for nutrients (protein, carbohydrates, fat, etc. per standard).","evidenceRequired":"Lab analysis or formulation data","commonNonConformities":"Using incorrect conversion factors"},{"code":"FD_2233_19","titleAr":"هل تم حساب البروتين باستخدام معامل التحويل الصحيح؟","titleEn":"Is protein calculated using the correct conversion factor?","category":"Calculation","priority":"Medium","compliantWhen":"Correct nitrogen conversion factor used","knowledgeBaseAr":"يجب حساب محتوى البروتين باستخدام معامل تحويل النيتروجين المناسب لنوع الغذاء وفقاً للائحة.","knowledgeBaseEn":"Protein content must be calculated using appropriate nitrogen conversion factor for food type per standard.","evidenceRequired":"Protein calculation documentation","commonNonConformities":"Wrong conversion factor for protein type"},{"code":"FD_2233_20","titleAr":"هل يُعبّر عن الطاقة لكل 100غ أو 100مل أو للعبوة الفردية؟","titleEn":"Is energy expressed per 100g or 100ml or per single-serving package?","category":"Format","priority":"High","compliantWhen":"Energy per 100g/100ml or per package shown","knowledgeBaseAr":"يجب عرض الطاقة لكل 100 غرام أو 100 مل، أو لكل عبوة أحادية الحصة عند الاقتضاء.","knowledgeBaseEn":"Energy must be displayed per 100g or 100ml, or per single-serving package when applicable.","evidenceRequired":"Nutrition panel layout review","commonNonConformities":"Energy per serving only (without 100g/ml)"},{"code":"FD_2233_21","titleAr":"هل يُعبّر عن البروتين والكربوهيدرات والدهون بالجرام؟","titleEn":"Are protein, carbohydrates, and fat expressed in grams?","category":"Format","priority":"Medium","compliantWhen":"Protein/carbs/fat in grams (g)","knowledgeBaseAr":"يجب التعبير عن البروتين والكربوهيدرات والدهون بالغرام (g).","knowledgeBaseEn":"Protein, carbohydrates, and fat must be expressed in grams (g).","evidenceRequired":"Unit verification","commonNonConformities":"Using wrong units (mg, %, etc.)"},{"code":"FD_2233_22","titleAr":"هل يُعبّر عن الفيتامينات والمعادن بالوحدات المترية الصحيحة؟","titleEn":"Are vitamins and minerals expressed in correct metric units?","category":"Format","priority":"Medium","compliantWhen":"V&M in correct metric units (mg, µg)","knowledgeBaseAr":"يجب استخدام الوحدات المترية المعتمدة لكل فيتامين أو معدن (مثل mg أو µg).","knowledgeBaseEn":"Approved metric units must be used for each vitamin or mineral (such as mg or µg).","evidenceRequired":"Unit verification","commonNonConformities":"Mixing units or using IU incorrectly"},{"code":"FD_2233_23","titleAr":"هل تم إظهار النسبة المئوية للقيمة اليومية (%DV) عند الحاجة؟","titleEn":"Is %Daily Value (%DV) shown when required?","category":"Format","priority":"High","compliantWhen":"%DV shown based on approved reference values","knowledgeBaseAr":"عندما تتطلب اللائحة ذلك، يجب عرض النسبة المئوية للقيمة اليومية (%DV) باستخدام القيم المرجعية المعتمدة.","knowledgeBaseEn":"When standard requires, %Daily Value (%DV) must be displayed using approved reference values.","evidenceRequired":"%DV calculation and display","commonNonConformities":"Missing %DV when required, wrong reference"},{"code":"FD_2233_24","titleAr":"هل تُعرَض الكربوهيدرات بشكل صحيح مع السكريات عند الحاجة؟","titleEn":"Are carbohydrates displayed correctly with sugars when required?","category":"Format","priority":"Low","compliantWhen":"Carbs shown with sugars breakdown properly","knowledgeBaseAr":"يجب عرض الكربوهيدرات وفق الترتيب المحدد في اللائحة، مع إظهار السكريات عند الاقتضاء.","knowledgeBaseEn":"Carbohydrates must be displayed per standard order, with sugars shown when required.","evidenceRequired":"Carbohydrate display review","commonNonConformities":"Sugars not indented under carbohydrates"},{"code":"FD_2233_25","titleAr":"هل تُرتّب الدهون ومشتقاتها بالصيغة المطلوبة؟","titleEn":"Are fats and their derivatives arranged in the required format?","category":"Format","priority":"Low","compliantWhen":"Fats arranged in required order","knowledgeBaseAr":"يجب ترتيب الدهون ومكوناتها وفق التسلسل المحدد في اللائحة.","knowledgeBaseEn":"Fats and their components must be arranged per sequence specified in standard.","evidenceRequired":"Fat display sequence review","commonNonConformities":"Wrong sequence of fat components"},{"code":"FD_2233_26","titleAr":"هل تستخدم معاملات تحويل السعرات بشكل صحيح (إذا كانت اختيارية)؟","titleEn":"Are calorie conversion factors used correctly (if optional)?","category":"Calculation","priority":"Low","compliantWhen":"Optional factors applied correctly","knowledgeBaseAr":"عند استخدام معاملات تحويل السعرات الحرارية يجب تطبيقها وفق القيم المعتمدة في اللائحة.","knowledgeBaseEn":"When using calorie conversion factors, they must be applied per approved values in standard.","evidenceRequired":"Conversion factor documentation","commonNonConformities":"Misapplying optional conversion factors"},{"code":"FD_2233_27","titleAr":"هل تمت إضافة عبارة القيمة اليومية لـ 2000 سعرة حرارية عند استخدام %DV؟","titleEn":"Is the 2000-calorie daily value statement added when %DV is used?","category":"Format","priority":"Medium","compliantWhen":"2000 kcal statement present when using %DV","knowledgeBaseAr":"عند عرض النسبة المئوية للقيمة اليومية (%DV) يجب تضمين بيان القيمة اليومية المبني على 2000 سعرة حرارية إذا تطلبت اللائحة ذلك.","knowledgeBaseEn":"When displaying %DV, the 2000-calorie daily value statement must be included if required by standard.","evidenceRequired":"Footer statement review","commonNonConformities":"Missing daily value footnote"},{"code":"FD_2233_28","titleAr":"هل تُستخدم القيم الصفرية أو (<) فقط عندما تسمح بها المواصفة؟","titleEn":"Are zero or (<) values used only when permitted by the standard?","category":"Values","priority":"High","compliantWhen":"Zero/<values used only per standard rules","knowledgeBaseAr":"لا يجوز استخدام القيم صفر (0) أو (<) إلا في الحالات والحدود التي تسمح بها اللائحة.","knowledgeBaseEn":"Zero (0) or (<) values may only be used in cases and limits permitted by standard.","evidenceRequired":"Value verification against standard","commonNonConformities":"Using 0 when actual value requires declaration"},{"code":"FD_2233_29","titleAr":"هل تم تقريب القيم الغذائية وفق قواعد التقريب؟","titleEn":"Are nutritional values rounded according to rounding rules?","category":"Values","priority":"Medium","compliantWhen":"Values rounded per standard rounding rules","knowledgeBaseAr":"يجب تقريب القيم التغذوية وفقاً لقواعد التقريب المحددة في اللائحة.","knowledgeBaseEn":"Nutritional values must be rounded according to rounding rules specified in standard.","evidenceRequired":"Rounding verification","commonNonConformities":"Over-rounding or under-rounding values"},{"code":"FD_2233_30","titleAr":"هل القيم الغذائية ضمن حدود التفاوت المقبولة؟","titleEn":"Are nutritional values within acceptable tolerance limits?","category":"Values","priority":"Critical","compliantWhen":"Declared values within tolerance limits","knowledgeBaseAr":"يجب أن تقع القيم المعلنة ضمن حدود التسامح المقبولة مقارنة بالقيم الفعلية للمنتج.","knowledgeBaseEn":"Declared values must fall within acceptable tolerance limits compared to actual product values.","evidenceRequired":"Lab analysis comparison","commonNonConformities":"Values outside acceptable tolerance range"},{"code":"FD_2233_31","titleAr":"هل تمثّل القيم المُعلنة المتوسط الحقيقي للمنتج؟","titleEn":"Do declared values represent a true average of the product?","category":"Values","priority":"High","compliantWhen":"Values represent true product average","knowledgeBaseAr":"يجب أن تمثّل القيم التغذوية متوسطاً حقيقياً يعكس المنتج طوال فترة صلاحيته.","knowledgeBaseEn":"Nutritional values must represent a true average reflecting the product throughout shelf life.","evidenceRequired":"Averaging methodology review","commonNonConformities":"Values based on single batch only"},{"code":"FD_2233_32","titleAr":"هل تُعرَض بيانات التغذية في شكل جدول (أو خطي إذا كانت المساحة محدودة)؟","titleEn":"Is nutrition data displayed in a table format (or linear if space is limited)?","category":"Presentation","priority":"Medium","compliantWhen":"Data in table format (linear if space limited)","knowledgeBaseAr":"يجب عرض البيانات التغذوية بصيغة جدول، ويُسمح بالصيغة الخطية عند عدم توفر مساحة كافية وفقاً للائحة.","knowledgeBaseEn":"Nutrition data must be displayed in table format, linear format permitted if insufficient space per standard.","evidenceRequired":"Layout verification","commonNonConformities":"Scattered data, no clear table structure"},{"code":"FD_2233_33","titleAr":"هل تُرتّب المُغذّيات بالترتيب المعتمد؟","titleEn":"Are nutrients arranged in the approved order?","category":"Presentation","priority":"Low","compliantWhen":"Nutrients in approved sequence order","knowledgeBaseAr":"يجب أن يتطابق ترتيب المغذيات مع التسلسل المحدد في اللائحة.","knowledgeBaseEn":"Nutrient order must match sequence specified in standard.","evidenceRequired":"Nutrient sequence review","commonNonConformities":"Random nutrient arrangement"},{"code":"FD_2233_34","titleAr":"هل يُبرز حجم الخط الطاقة وحجم الحصة؟","titleEn":"Does font size emphasize energy and serving size?","category":"Presentation","priority":"Low","compliantWhen":"Energy and serving size emphasized","knowledgeBaseAr":"يجب أن يتطابق حجم الخط والتأكيد على الطاقة وحجم الحصة مع متطلبات العرض في اللائحة.","knowledgeBaseEn":"Font size and emphasis on energy and serving size must match presentation requirements in standard.","evidenceRequired":"Font size measurement","commonNonConformities":"All text same size, no emphasis"},{"code":"FD_2233_35","titleAr":"هل يوجد تباين كافٍ بين النص والخلفية؟","titleEn":"Is there sufficient contrast between text and background?","category":"Presentation","priority":"Medium","compliantWhen":"Sufficient text/background contrast","knowledgeBaseAr":"يجب أن يكون النص واضحاً ومقروءاً مع وجود تباين كافٍ بين النص والخلفية.","knowledgeBaseEn":"Text must be clear and legible with sufficient contrast between text and background.","evidenceRequired":"Contrast assessment","commonNonConformities":"Poor readability, low contrast"},{"code":"FD_2233_36","titleAr":"هل يمتثل العرض الرقمي لمتطلبات المواصفة؟","titleEn":"Does the numerical display comply with standard requirements?","category":"Presentation","priority":"Low","compliantWhen":"Numbers and units per standard format","knowledgeBaseAr":"يجب أن يتطابق تنسيق الأرقام والوحدات وطريقة العرض مع متطلبات اللائحة.","knowledgeBaseEn":"Number formatting, units, and display method must match standard requirements.","evidenceRequired":"Numeric display review","commonNonConformities":"Inconsistent number formatting"},{"code":"FD_2233_37","titleAr":"في حال استخدام معلومات تغذية تكميلية، هل هي مكمّلة (وليست بديلاً)؟","titleEn":"If supplementary nutrition info is used, is it complementary (not replacement)?","category":"Supplementary Info","priority":"Medium","compliantWhen":"Supplementary info complements, doesn't replace","knowledgeBaseAr":"يجوز استخدام المعلومات التغذوية التكميلية شريطة أن تكمّل البيانات التغذوية الإلزامية وألا تحل محلها.","knowledgeBaseEn":"Supplementary nutrition information may be used provided it complements mandatory nutrition data and does not replace it.","evidenceRequired":"Additional nutrition info review","commonNonConformities":"FOP replacing back-of-pack nutrition facts"}],"titleAr":"بطاقة القيمة الغذائية (SFDA FD 2233)","titleEn":"Nutrition Labeling (SFDA FD 2233)","standard":"SFDA FD 2233","itemCount":37},{"code":"FD_2333","items":[{"code":"FD_2333_01","titleAr":"هل يحتوي المنتج على ادّعاء صحي أو غذائي؟","titleEn":"Does the product contain a health or nutrition claim?","decisionRule":"Identify if claim exists to determine applicable verification path.","applicability":"Any claim on label","referenceRange":"SFDA FD 2333; Table 1!A1:R376; Table 2!A1:R50","knowledgeBaseAr":"هل يحتوي المنتج على ادعاء صحي أو تغذوي؟","evidenceRequired":"Label review for claim presence"},{"code":"FD_2333_02","titleAr":"في حال وجود ادّعاء، هل تم الإفصاح عن كمية المُغذّي ذي الصلة بالادّعاء؟","titleEn":"If claim exists, is the quantity of nutrient related to the claim disclosed?","decisionRule":"Compliant when nutrient quantity supporting the claim is disclosed.","applicability":"Nutrient quantity disclosure","referenceRange":"SFDA FD 2333; Table 1!M; Table 2!K","knowledgeBaseAr":"إذا وجد ادعاء، هل تم الإفصاح عن كمية المغذي المتعلق بالادعاء؟","evidenceRequired":"Label shows nutrient amount per serving"},{"code":"FD_2333_03","titleAr":"هل تُطبّق متطلبات البطاقة الغذائية عند استخدام الادّعاءات؟","titleEn":"Are nutrition labeling requirements applied when using claims?","decisionRule":"Compliant when full nutrition labeling accompanies any claim.","applicability":"Nutrition facts panel","referenceRange":"SFDA FD 2333; SFDA FD 2233","knowledgeBaseAr":"هل تم تطبيق متطلبات البطاقة التغذوية عند استخدام الادعاءات؟","evidenceRequired":"Complete nutrition label present"},{"code":"FD_2333_04","titleAr":"هل تمت إضافة عبارة عن أهمية النظام الغذائي المتوازن؟ (للادّعاءات الصحية)","titleEn":"Is a statement about balanced diet importance added? (for health claims)","decisionRule":"Compliant when health claim includes balanced diet statement.","applicability":"Health claims only","referenceRange":"SFDA FD 2333; Table 1!M (Conditions)","knowledgeBaseAr":"هل تمت إضافة عبارة عن أهمية النظام الغذائي المتوازن؟ (للادعاءات الصحية)","evidenceRequired":"Balanced diet statement on label"},{"code":"FD_2333_05","titleAr":"هل المنتج خالٍ من ادّعاءات معدّل أو مقدار فقدان الوزن؟","titleEn":"Is the product free from weight loss rate/amount claims?","decisionRule":"Compliant when no prohibited weight loss claims present.","applicability":"Weight loss claims","referenceRange":"SFDA FD 2333 prohibited claims","knowledgeBaseAr":"هل المنتج خالٍ من ادعاءات معدل أو كمية فقدان الوزن؟","evidenceRequired":"No specific weight loss rate/amount claims"},{"code":"FD_2333_06","titleAr":"هل المنتج خالٍ من ادّعاءات تتضمّن توصيات الأطباء؟","titleEn":"Is the product free from claims containing physician recommendations?","decisionRule":"Compliant when no medical endorsement claims present.","applicability":"Physician/medical endorsements","referenceRange":"SFDA FD 2333 prohibited claims","knowledgeBaseAr":"هل المنتج خالٍ من ادعاءات تحتوي على توصيات الأطباء؟","evidenceRequired":"No physician recommendation claims"},{"code":"FD_2333_07","titleAr":"هل المنتج خالٍ من ادّعاءات الوقاية أو العلاج أو الشفاء؟","titleEn":"Is the product free from prevention/treatment/cure claims?","decisionRule":"Compliant when no disease-related claims present.","applicability":"Disease claims","referenceRange":"SFDA FD 2333 prohibited claims","knowledgeBaseAr":"هل المنتج خالٍ من ادعاءات الوقاية/العلاج/الشفاء؟","evidenceRequired":"No prevention/treatment/cure claims"},{"code":"FD_2333_08","titleAr":"هل جميع الادّعاءات قابلة للتحقق؟","titleEn":"Are all claims verifiable?","decisionRule":"Compliant when each claim can be verified against permitted lists.","applicability":"All claims on label","referenceRange":"SFDA FD 2333; Table 1; Table 2","knowledgeBaseAr":"هل جميع الادعاءات قابلة للتحقق؟","evidenceRequired":"Scientific evidence or regulatory listing"},{"code":"FD_2333_09","titleAr":"هل الادّعاءات خالية من العبارات التي لا معنى لها أو المبالغات؟","titleEn":"Are claims free from meaningless statements or exaggerations?","decisionRule":"Compliant when claims are factual without exaggeration.","applicability":"All claim wording","referenceRange":"SFDA FD 2333","knowledgeBaseAr":"هل الادعاءات خالية من العبارات غير المفيدة أو المبالغات؟","evidenceRequired":"Clear, accurate, non-misleading language"},{"code":"FD_2333_10","titleAr":"في حال استخدام ادّعاء صحي، هل هو مدرج في الجدول (1)؟","titleEn":"If using health claim, is the claim listed in Table (1)?","decisionRule":"Compliant only when health claim matches Table 1 entry.","applicability":"Health claim text","referenceRange":"Table 1!A3:R376","knowledgeBaseAr":"إذا كان يستخدم ادعاء صحي، هل الادعاء مدرج في الجدول (1)؟","evidenceRequired":"Exact match in Table 1 permitted claims"},{"code":"FD_2333_11","titleAr":"في حال استخدام ادّعاء صحي، هل تم استيفاء جميع شروط الاستخدام؟","titleEn":"If using health claim, are all conditions of use met?","decisionRule":"Compliant when all Table 1 conditions for the claim are satisfied.","applicability":"Matched claim conditions","referenceRange":"Table 1!M (Conditions of use)","knowledgeBaseAr":"إذا كان يستخدم ادعاء صحي، هل تم استيفاء جميع شروط الاستخدام؟","evidenceRequired":"Product meets all conditions in Table 1"},{"code":"FD_2333_12","titleAr":"في حال استخدام ادّعاء غذائي، هل هو مدرج في الجدول (2)؟","titleEn":"If using nutrition claim, is the claim listed in Table (2)?","decisionRule":"Compliant only when nutrition claim matches Table 2 entry.","applicability":"Nutrition claim text","referenceRange":"Table 2!A3:R50","knowledgeBaseAr":"إذا كان يستخدم ادعاء تغذوي، هل الادعاء مدرج في الجدول (2)؟","evidenceRequired":"Exact match in Table 2 permitted claims"},{"code":"FD_2333_13","titleAr":"في حال استخدام ادّعاء غذائي، هل تم استيفاء جميع شروط الاستخدام؟","titleEn":"If using nutrition claim, are all conditions of use met?","decisionRule":"Compliant when all Table 2 conditions for the claim are satisfied.","applicability":"Matched claim conditions","referenceRange":"Table 2!K (Conditions of use)","knowledgeBaseAr":"إذا كان يستخدم ادعاء تغذوي، هل تم استيفاء جميع شروط الاستخدام؟","evidenceRequired":"Product meets all conditions in Table 2"},{"code":"FD_2333_14","titleAr":"هل صياغة الادّعاء واضحة وصحيحة وغير مضلِّلة؟","titleEn":"Is the claim wording clear, correct, and not misleading?","decisionRule":"Compliant when claim wording aligns with regulatory requirements.","applicability":"Final claim review","referenceRange":"SFDA FD 2333; Table 1; Table 2","knowledgeBaseAr":"هل صياغة الادعاء واضحة وصحيحة وغير مضللة؟","evidenceRequired":"Wording matches permitted claim language"}],"titleAr":"الادعاءات الصحية والغذائية (SFDA FD 2333)","titleEn":"Health & Nutrition Claims (SFDA FD 2333)","standard":"SFDA FD 2333","itemCount":14},{"code":"FD_2500","items":[{"code":"FD_2500_01","titleAr":"هل تم تحديد جميع المضافات المدرجة في المكوّنات؟","titleEn":"Have all additives listed in the ingredients been identified?","decisionRule":"Compliant when every declared additive is identified.","applicability":"All additives declared in the ingredient list","referenceRange":"SFDA-FD-2500!A2:B2; GMP All Additives!A5:E187; Food additive!A3:D51","knowledgeBaseAr":"تم تحديد جميع المواد المضافة الواردة في قائمة المكونات.","evidenceRequired":"Ingredient list with additive names and/or INS numbers."},{"code":"FD_2500_02","titleAr":"هل جميع المضافات المستخدمة مصرّح بها لفئة الأغذية 13.6 – المكملات الغذائية؟","titleEn":"Are all additives used authorized for Food Category 13.6 – Food Supplements?","decisionRule":"Compliant only when every additive is listed for Category 13.6.","applicability":"Match each additive name or INS number against Category 13.6","referenceRange":"SFDA-FD-2500!A3:B3; Food additive!A3:D51","knowledgeBaseAr":"جميع المواد المضافة المستخدمة مصرح بها لفئة Food Category 13.6 – Food Supplements.","evidenceRequired":"Exact match in the Category 13.6 permitted-additives table."},{"code":"FD_2500_03","titleAr":"هل تم استيفاء الحدود القصوى المسموح بها أو متطلبات ممارسات التصنيع الجيدة (GMP) لكل مضاف؟","titleEn":"Are the maximum permitted levels or GMP requirements met for each additive?","decisionRule":"Compliant when each quantitative limit is met, or GMP use is justified at the minimum technologically necessary level.","applicability":"Maximum level in mg/kg or GMP designation","referenceRange":"SFDA-FD-2500!A4:B4; GMP All Additives!A5:E187; Food additive!A3:D51","knowledgeBaseAr":"تم الالتزام بالحدود القصوى للاستخدام أو بمتطلبات GMP لكل مادة مضافة.","evidenceRequired":"Formula quantity/concentration and the applicable max level or documented GMP justification."},{"code":"FD_2500_04","titleAr":"هل تم الالتزام بجميع القيود وملاحظات المواصفة المنطبقة على كل مضاف؟","titleEn":"Are all restrictions and specification notes applicable to each additive complied with?","decisionRule":"Compliant when all linked notes and restrictions are satisfied.","applicability":"All note numbers shown for the matched additive","referenceRange":"SFDA-FD-2500!A5:B5; Food additive!A3:D51","knowledgeBaseAr":"تم الالتزام بجميع القيود والملاحظات (Notes) الواردة في المواصفة لكل مادة مضافة.","evidenceRequired":"Assessment against every note number linked to the additive."},{"code":"FD_2500_05","titleAr":"عند استخدام الجيلاتين أو الليسيثين أو المونو والداي جليسيريد، هل تم التحقق من مصدرها وفق المتطلبات النظامية؟","titleEn":"Where gelatin, lecithin, or mono- and diglycerides are used, has their source been verified in accordance with regulatory requirements?","decisionRule":"Compliant when required source documentation is available and acceptable.","applicability":"Gelatin; Lecithin (INS 322(i)); Mono- and diglycerides (INS 471)","referenceRange":"SFDA-FD-2500!A6:B6; GMP All Additives!A5:E187","knowledgeBaseAr":"في حال استخدام الجيلاتين (Gelatin) أو الليسيثين (Lecithin) أو الجلسريدات الأحادية والثنائية (Mono- & Diglycerides)، تم التحقق من مصدرها وفق المتطلبات التنظيمية.","evidenceRequired":"Supplier declaration, origin statement, halal/animal-source evidence where applicable."},{"code":"FD_2500_06","titleAr":"هل المنتج خالٍ من أي مضاف غير مصرّح به أو غير مدرج للمكملات الغذائية (الفئة 13.6)؟","titleEn":"Is the product free from any additive that is unauthorized or not listed for Food Supplements (Category 13.6)?","decisionRule":"Compliant when no unauthorized or unmatched additive remains.","applicability":"Any ingredient additive not found in the Category 13.6 table","referenceRange":"SFDA-FD-2500!A7:B7; GMP All Additives!A5:E187; Food additive!A3:D51","knowledgeBaseAr":"لا توجد أي مادة مضافة غير مصرح بها أو غير مدرجة لفئة Food Supplements (13.6).","evidenceRequired":"Reconciliation showing no ingredient additive remains unmatched to Category 13.6."},{"code":"FD_2500_07","titleAr":"هل جميع المضافات المستخدمة مسموحة للفئة 13.6 – المكملات الغذائية؟","titleEn":"Are all additives used permitted for Category 13.6 – Food Supplements?","decisionRule":"Compliant only when every additive is listed for Category 13.6.","applicability":"Match each additive name or INS number against Category 13.6","referenceRange":"SFDA-FD-2500!A10:B10; Food additive!A3:D51","knowledgeBaseAr":"جميع المواد المضافة المستخدمة مسموح بها لفئة 13.6 Food Supplements.","evidenceRequired":"Exact match in the Category 13.6 permitted-additives table."},{"code":"FD_2500_08","titleAr":"هل تم الالتزام بالحدود القصوى أو متطلبات GMP لكل مضاف؟","titleEn":"Are the maximum levels or GMP requirements complied with for each additive?","decisionRule":"Compliant when each quantitative limit is met, or GMP use is justified.","applicability":"Maximum level in mg/kg or GMP designation","referenceRange":"SFDA-FD-2500!A11:B11; GMP All Additives!A5:E187; Food additive!A3:D51","knowledgeBaseAr":"تم الالتزام بالحدود القصوى أو GMP لكل مادة مضافة.","evidenceRequired":"Formula quantity/concentration and the applicable max level or documented GMP justification."},{"code":"FD_2500_09","titleAr":"عند استخدام INS 960 أو محلّيات الستيفيا الأخرى، هل تم حساب الحد كمكافئات ستيفيول؟ (ملاحظة 26)","titleEn":"Where INS 960 or other stevia sweeteners are used, has the limit been calculated as Steviol Equivalents? (Note 26)","decisionRule":"Compliant when the Steviol Equivalent result is within the applicable limit.","applicability":"Steviol glycosides; INS 960 series; Note 26","referenceRange":"SFDA-FD-2500!A12:B12; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند وجود INS 960 أو غيره من محليات الستيفيا تم احتساب الحد بوحدة Steviol Equivalents. (ملاحظة 26)","evidenceRequired":"Calculation expressed as Steviol Equivalents."},{"code":"FD_2500_10","titleAr":"عند استخدام البنزوات، هل تم حساب الحد كحمض بنزويك؟ (ملاحظة 13)","titleEn":"Where benzoates are used, has the limit been calculated as Benzoic Acid? (Note 13)","decisionRule":"Compliant when the Benzoic Acid equivalent is within the applicable limit.","applicability":"Benzoates; INS 210-213; Note 13","referenceRange":"SFDA-FD-2500!A13:B13; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند وجود بنزوات تم احتساب الحد على أساس Benzoic Acid. (ملاحظة 13)","evidenceRequired":"Calculation expressed as Benzoic Acid."},{"code":"FD_2500_11","titleAr":"عند استخدام السوربات، هل تم حساب الحد كحمض سوربيك؟ (ملاحظة 42)","titleEn":"Where sorbates are used, has the limit been calculated as Sorbic Acid? (Note 42)","decisionRule":"Compliant when the Sorbic Acid equivalent is within the applicable limit.","applicability":"Sorbates; INS 200-203; Note 42","referenceRange":"SFDA-FD-2500!A14:B14; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند وجود سوربات تم احتساب الحد على أساس Sorbic Acid. (ملاحظة 42)","evidenceRequired":"Calculation expressed as Sorbic Acid."},{"code":"FD_2500_12","titleAr":"عند استخدام التارترات، هل تم حساب الحد كحمض طرطير؟ (ملاحظة 45)","titleEn":"Where tartrates are used, has the limit been calculated as Tartaric Acid? (Note 45)","decisionRule":"Compliant when the Tartaric Acid equivalent is within the applicable limit.","applicability":"Tartrates; INS 334, 335(ii), 337; Note 45","referenceRange":"SFDA-FD-2500!A15:B15; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند وجود الطرطرات تم احتساب الحد على أساس Tartaric Acid. (ملاحظة 45)","evidenceRequired":"Calculation expressed as Tartaric Acid."},{"code":"FD_2500_13","titleAr":"عند استخدام الفوسفات، هل تم حساب الحد بناءً على الفوسفور؟ (ملاحظة 33)","titleEn":"Where phosphates are used, has the limit been calculated based on Phosphorus? (Note 33)","decisionRule":"Compliant when the Phosphorus equivalent is within the applicable limit.","applicability":"Phosphates; listed phosphate INS numbers; Note 33","referenceRange":"SFDA-FD-2500!A16:B16; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند استخدام الفوسفات تم احتساب الحد على أساس Phosphorus. (ملاحظة 33)","evidenceRequired":"Calculation expressed as Phosphorus."},{"code":"FD_2500_14","titleAr":"عند استخدام الأسبرتام أو أسيسولفام كي أو INS 962، هل تم حساب الحد المجمّع وفق متطلبات المواصفة؟ (الملاحظات 113 و188 و191)","titleEn":"Where Aspartame, Acesulfame K, or INS 962 are used, has the combined limit been calculated according to the specification requirements? (Notes 113, 188, and 191)","decisionRule":"Compliant when individual and combined sweetener limits are satisfied.","applicability":"Acesulfame K INS 950; Aspartame INS 951; Salt INS 962; Notes 188, 191, 113","referenceRange":"SFDA-FD-2500!A17:B17; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند وجود Aspartame / Acesulfame K / INS 962 تم احتساب الحد المشترك وفق متطلبات المواصفة. (الملاحظات 113، 188، 191)","evidenceRequired":"Combined sweetener calculation using the applicable notes."},{"code":"FD_2500_15","titleAr":"عند استخدام مضادات الأكسدة BHA أو BHT أو بروبيل جالات، هل تم حساب الحدود الفردية أو المجمّعة بشكل صحيح؟ (ملاحظة 196)","titleEn":"Where BHA, BHT, or Propyl Gallate antioxidants are used, have the individual or combined limits been calculated correctly? (Note 196)","decisionRule":"Compliant when individual and combined antioxidant limits are satisfied.","applicability":"BHA INS 320; BHT INS 321; Propyl Gallate INS 310; Note 196","referenceRange":"SFDA-FD-2500!A18:B18; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند استخدام مضادات الأكسدة BHA/BHT/Propyl Gallate تم احتساب الحدود منفردة أو مجتمعة. (ملاحظة 196)","evidenceRequired":"Individual and combined antioxidant calculation."},{"code":"FD_2500_16","titleAr":"عند استخدام إسترات السكروز (INS 473 أو 473a أو 474)، هل تم تطبيق الحد فردياً أو مجتمعاً؟ (ملاحظة 348)","titleEn":"Where Sucrose Esters (INS 473, 473a, or 474) are used, has the limit been applied individually or in combination? (Note 348)","decisionRule":"Compliant when the individual/combined limit is satisfied.","applicability":"INS 473, 473a, 474; Note 348","referenceRange":"SFDA-FD-2500!A19:B19; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"عند استخدام Sucrose Esters (INS 473/473a/474) تم تطبيق الحد منفردًا أو مجتمعًا. (ملاحظة 348)","evidenceRequired":"Individual and combined Sucrose Ester calculation."},{"code":"FD_2500_17","titleAr":"إذا كان المنتج مكمّلاً قابلاً للمضغ، هل المضافات المستخدمة مسموحة لهذا الشكل؟ (ملاحظة 203)","titleEn":"If the product is a chewable supplement, are the additives used permitted for this form? (Note 203)","decisionRule":"Compliant when Note 203 conditions are satisfied; otherwise N/A.","applicability":"Chewable supplement restrictions; Note 203","referenceRange":"SFDA-FD-2500!A20:B20; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"إذا كان المنتج Chewable Supplement فالمواد المضافة المستخدمة مسموح بها لهذه الفئة. (ملاحظة 203)","evidenceRequired":"Confirmation that the additive is permitted for chewable supplements."},{"code":"FD_2500_18","titleAr":"إذا كان المنتج كبسولة أو قرصاً، هل تم الالتزام بالقيود المنطبقة على هذا الشكل الجرعي؟ (ملاحظة 417)","titleEn":"If the product is a capsule or tablet, are the restrictions applicable to this dosage form complied with? (Note 417)","decisionRule":"Compliant when Note 417 conditions are satisfied; otherwise N/A.","applicability":"Capsule/tablet restrictions; Note 417","referenceRange":"SFDA-FD-2500!A21:B21; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"إذا كان المنتج Capsule أو Tablet فتم الالتزام بالقيود الخاصة بهذه الهيئة الدوائية. (ملاحظة 417)","evidenceRequired":"Confirmation that capsule/tablet-specific restrictions are satisfied."},{"code":"FD_2500_19","titleAr":"إذا كان المنتج يحتوي على زيت السمك، هل تم الالتزام بالحدود المنطبقة، بما في ذلك 6,000 ملغ/كغم عند الاقتضاء؟ (ملاحظة 418)","titleEn":"If the product contains fish oil, are the applicable limits complied with, including 6,000 mg/kg where applicable? (Note 418)","decisionRule":"Compliant when Note 418 and the applicable 6000 mg/kg limit are satisfied; otherwise N/A.","applicability":"Fish oil condition and 6000 mg/kg where applicable; Note 418","referenceRange":"SFDA-FD-2500!A22:B22; Food additive!A3:D51 (filter by Notes/INS)","knowledgeBaseAr":"إذا كان المنتج يحتوي على Fish Oil فقد تم الالتزام بالحدود الخاصة به (6000 mg/kg عند انطباقها). (ملاحظة 418)","evidenceRequired":"Fish-oil applicability assessment and concentration calculation."}],"titleAr":"المضافات الغذائية (SFDA FD 2500)","titleEn":"Food Additives (SFDA FD 2500)","standard":"SFDA FD 2500","itemCount":19}]$v$::jsonb,
  1, true
) ON CONFLICT ("subCategoryId","code") DO NOTHING;

