INSERT INTO "RequiredDocument" ("id","serviceItemId","code","nameEn","nameAr","mandatory","acceptedMimeTypes","maxSizeMb","helpEn","helpAr","sortOrder") VALUES (
  $v$rd_supplement_label_full_packaging_photos$v$,
  (SELECT "id" FROM "ServiceItem" WHERE "code" = $v$SUPPLEMENT_LABEL_FULL$v$),
  $v$PACKAGING_PHOTOS$v$, $v$Packaging photographs$v$, $v$صور العبوة$v$, false, ARRAY[$v$image/png$v$, $v$image/jpeg$v$, $v$application/pdf$v$]::text[], 50, $v$Clear photos of primary and secondary packaging if PDF panels are incomplete.$v$, $v$صور واضحة للعبوة الأولية والثانوية إذا كانت ألواح ملف PDF غير مكتملة.$v$, 5
) ON CONFLICT ("serviceItemId","code") DO NOTHING;

-- COSMETIC_LABEL_AR_EN  (Cosmetic label assessment (AR/EN))
INSERT INTO "ServiceItem" ("id","subCategoryId","code","nameEn","nameAr","descEn","descAr","basePrice","vatRate","resubmissionPricePct","slaHours","freeResubmissions","maxResubmissions","productAttrSchema","checkSets","sortOrder","active") VALUES (
  $v$svc_cosmetic_label_ar_en$v$,
  (SELECT "id" FROM "SubCategory" WHERE "code" = $v$COSMETIC_LABELLING$v$),
  $v$COSMETIC_LABEL_AR_EN$v$, $v$Cosmetic label assessment (AR/EN)$v$, $v$تقييم بطاقة مستحضر التجميل (عربي/إنجليزي)$v$, $v$Labelling articles review under GSO 1943 for leave-on and rinse-off products.$v$, $v$مراجعة مواد بطاقة البيان وفق GSO 1943 للمنتجات التي تُترك أو تُشطف.$v$,
  3200, 0.15, 0.5, 96, 0, 3,
  $v${"type":"object","required":["product_type","target_group"],"properties":{"product_type":{"enum":["leave-on","rinse-off","oral-care","hair","nail","perfume"],"type":"string","helpAr":"حدود تركيز الملاحق تختلف بين المنتجات التي تُترك والتي تُشطف.","helpEn":"Annex concentration limits differ for leave-on vs rinse-off products.","titleAr":"نوع المنتج","titleEn":"Product type"},"target_group":{"enum":["general","children","professional"],"type":"string","helpAr":"يؤثر على عبارات التحذير الإلزامية على البطاقة.","helpEn":"Affects mandatory warning statements on the label.","titleAr":"الفئة المستهدفة","titleEn":"Target group"}}}$v$::jsonb,
  $v$[{"code":"GSO_1943","titleAr":"GSO 1943 — بطاقة مستحضرات التجميل","titleEn":"GSO 1943 — Cosmetic labelling"},{"code":"ANNEX_SCREEN","titleAr":"فحص الملاحق","titleEn":"Annex screening"}]$v$::jsonb,
  1, true
) ON CONFLICT ("subCategoryId","code") DO NOTHING;

